"""Self-contained interactive view of retained untrained native neural evaluations."""
from pathlib import Path
import json

ROOT=Path(__file__).resolve().parents[1]
data=json.loads((ROOT/'tests/project/fixtures/native-forest-flow-example.json').read_text())
assert data['synthetic']is True and data['trained']is False and data['optimizer_updates']==0
PAGE=r'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Mora-3 · Native forest heads</title>
<style>:root{color-scheme:light;--ink:#173746;--muted:#526572;--line:#cbd7d9;--accent:#087b7a;--paper:#f5f7f4}*{box-sizing:border-box}body{margin:0;background:var(--paper);color:var(--ink);font:16px/1.55 system-ui,sans-serif}main{max-width:1120px;margin:auto;padding:34px 24px}a{color:#086e7c}h1{font-size:clamp(30px,4vw,49px);line-height:1.13;letter-spacing:-.035em;max-width:840px}h2{font-size:24px;line-height:1.3;margin-top:0}.eyebrow{font-size:12px;text-transform:uppercase;letter-spacing:.13em;font-weight:750}.lead{max-width:870px}.notice{background:#edeade;border-left:4px solid #8e723d;padding:14px 18px;margin:22px 0}.controls{display:flex;gap:14px;flex-wrap:wrap;align-items:end;margin:22px 0}.controls label{display:flex;flex-direction:column;gap:5px;font-size:14px;font-weight:650}select,button{font:inherit;min-height:44px;border:1px solid #8fa8b2;border-radius:5px;background:white;color:var(--ink);padding:8px 12px}button{cursor:pointer}select:focus-visible,button:focus-visible,a:focus-visible{outline:3px solid #b16b35;outline-offset:3px}.grid{display:grid;grid-template-columns:1fr 1fr;gap:22px}.card{background:white;border:1px solid var(--line);border-radius:10px;padding:22px;min-width:0;margin-bottom:22px}.card svg{width:100%;height:auto;display:block}.caption{font-size:14px;color:var(--muted)}table{border-collapse:collapse;width:100%;font-size:14px}td,th{text-align:left;border-bottom:1px solid var(--line);padding:9px 5px;font-variant-numeric:tabular-nums}th{font-size:13px}code{font-size:13px;overflow-wrap:anywhere}ul{padding-left:21px}.wide{grid-column:1/-1}.stats{display:flex;gap:28px;flex-wrap:wrap;border-top:1px solid var(--accent);margin:25px 0;padding:15px 0}.stats strong{display:block;font-size:28px}.stats span{font-size:14px}footer{border-top:1px solid var(--line);padding-top:22px;font-size:14px;color:var(--muted)}.scroll{overflow:auto}#phase{font-weight:650}#vectors,#nearest{min-height:320px}details{margin-top:16px}summary{cursor:pointer}noscript{display:block;padding:20px;background:#fff} @media(max-width:700px){main{padding:22px 14px}.grid{grid-template-columns:1fr}.card{padding:16px}.controls>*{flex:1 1 140px}h2{font-size:21px}.stats{gap:20px}.card svg{min-width:0}table{font-size:12px}}</style></head><body><main>
<a href="../index.html">Mora-3 research</a><p class="eyebrow">Native neural components · Reproducible software evidence</p>
<h1>One shared forest representation.<br>Four trainable heads.</h1>
<p class="lead">Inspect the implemented conditional velocity field, learned analogy keys, token-slot decoder and criterion scorer. These controls replay retained computations from the actual native modules—not a browser mock of a trained model.</p>
<div class="notice"><strong>Randomly initialized model. Synthetic inputs. No training results.</strong> The example uses a five-node forest, width16 and a two-dimensional reasoning latent. Neither biological accuracy nor high-quality learned outputs is established. The token codebook and criterion labels are explicit test fixtures.</div>
<div class="stats"><div><span>Whole-forest candidates</span><strong id="candidate-count"></strong></div><div><span>New velocity parameters</span><strong id="parameter-count"></strong></div><div><span>Proposed controls implemented</span><strong id="control-count"></strong></div><div><span>Optimizer updates</span><strong>0</strong></div></div>
<div class="controls"><label>Available condition<select id="condition"><option value="1">1 · context A</option><option value="2">2 · context B</option></select></label><label>Flow-solver time<select id="time"><option value="0">0.00</option><option value="0.25">0.25</option><option value="0.5" selected>0.50</option><option value="0.75">0.75</option><option value="1">1.00</option></select></label><button id="export-field">Export field SVG</button><button id="export-data">Export diagnostic JSON</button></div>
<div class="grid"><section class="card"><h2>The actual conditional velocity</h2><div id="vectors"></div><p id="phase" aria-live="polite"></p><p class="caption">Circles show noisy latent states. Arrows show velocity over one solver-time unit, not a completed Euler step or physical displacement. Gray links are declared computational/temporal dependencies, not molecular bonds. All views use the same coordinate scale.</p></section>
<section class="card"><h2>Conditions stay fixed.<br>Hidden targets stay excluded.</h2><table><thead><tr><th>Node</th><th>v₁</th><th>v₂</th><th>Role</th></tr></thead><tbody id="velocity-values"></tbody></table><p class="caption">Node0 is the clamped source condition. Changing the hidden target from7 to999999 produced exactly <strong id="hidden-difference"></strong> maximum velocity difference in each retained case.</p><details><summary>Source and field bindings</summary><p>Context <code id="context-pin"></code></p><p>Velocity field <code id="field-pin"></code></p></details></section>
<section class="card"><h2>Nearest-token refinement</h2><div class="controls"><label>Generated node<select id="node"><option value="1">1 · left</option><option value="2">2 · left terminal</option><option value="3">3 · right</option><option value="4">4 · right terminal</option></select></label><label>Token slot<select id="slot"><option value="0">0</option><option value="1">1</option><option value="2">2</option><option value="3">3</option></select></label></div><div id="nearest"></div><p class="caption">Distances use all three codebook dimensions. The nearest permitted payload token or NODE_END wins; other structural controls are masked. This panel always uses context B and the declared complete candidate, independently of the velocity controls. No stop within the slot budget yields an explicit incomplete-decoding refusal.</p><button id="export-token">Export token SVG</button></section>
<section class="card"><h2>Keep quality criteria separate</h2><table><thead><tr><th>Candidate</th><th>Criterion A</th><th>Criterion B</th><th>Priority</th></tr></thead><tbody id="quality-values"></tbody></table><p class="caption">These are untrained sigmoid predictions on the four generated candidates. A declared weighted priority is not a hard-constraint verdict, a calibrated probability or biological evidence. Unknown quality labels are excluded from training loss rather than treated as failures.</p><h2 style="margin-top:30px">Retrieval with an exact reference</h2><p id="retrieval"></p><p class="caption">The native learned-key index excludes the shared group <code>memory:0</code>. Exact and one-cell search may return different sets. Distances are real L2 computations; semantic analogy accuracy is not measured by this fixture.</p></section>
<section class="card wide"><h2>What is implemented—and what remains</h2><table><thead><tr><th>Component</th><th>Implemented software</th><th>Not established here</th></tr></thead><tbody><tr><td>Conditional flow</td><td>All-node native field, masked loss, explicit generator, subtree regeneration</td><td>Trained trajectory quality; unknown-topology generation</td></tr><tr><td>Whole-forest analogy</td><td>Context-only learned query, full-forest key, group filtering, bounded approximate/exact index</td><td>Validated cross-domain correspondence; current admitted memory corpus</td></tr><tr><td>Token decoder</td><td>40 appended controls; learned token slots; frozen versioned codebook; strict grammar and refusal</td><td>Qualified real encoder/codebook export and token-aligned training corpus</td></tr><tr><td>Quality head</td><td>Per-node and whole-forest criterion predictions; explicit missing-label masks</td><td>Calibrated domain validators and demonstrated improvement</td></tr><tr><td>Campaign</td><td>Native owner/alias/checkpoint integration; guarded software tests</td><td>Full source/operator release; actual24+2 results and held-out evaluations</td></tr></tbody></table><p class="caption">The ordinary-attention μP family and legacy tropical operator are tested separately. No numerical μTransfer qualification of the extended tropical model is inferred. Additional distillation/preference training still requires an allocation beyond the unchanged26-run limit.</p></section></div>
<noscript>This page needs JavaScript for controls. Static matching SVG figures are included with the manuscript.</noscript>
<footer><p>Method basis: <a href="https://arxiv.org/abs/2210.02747">Flow Matching</a>; <a href="https://arxiv.org/abs/2205.14217">Diffusion-LM</a>; <a href="https://arxiv.org/abs/2203.03466">μTransfer</a>. This native graph/forest architecture is a Mora-3 adaptation, not a reproduction of those systems.</p><p><a href="flow-fot-refinement.html">Candidate refinement</a> · <a href="persistence-vectors.html">Persistence vectors</a> · <a href="../paper.html#native-forest-heads">Methods and evidence</a></p></footer>
<script id="data" type="application/json">__DATA__</script><script>
'use strict';const data=JSON.parse(document.getElementById('data').textContent);const $=id=>document.getElementById(id);const esc=x=>String(x).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));let current={condition:1,time:.5,node:1,slot:0};
const f=x=>Number(x).toFixed(6);const svg=(title,body)=>`<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 460 430" role="img" aria-label="${esc(title)}"><title>${esc(title)}</title><rect width="460" height="430" fill="white"/>${body}</svg>`;
let extent=Math.max(1,...data.rows.flatMap(r=>r.states.flatMap((v,i)=>v.map((z,d)=>Math.abs(z+r.velocity[i][d])))));extent=Math.ceil(extent*1.2*2)/2;
function fieldSvg(r){const x=z=>55+(z+extent)/(2*extent)*350,y=z=>365-(z+extent)/(2*extent)*315;let b=`<defs><marker id="tip" viewBox="0 0 10 10" refX="8" refY="5" markerWidth="5" markerHeight="5" orient="auto-start-reverse"><path d="M 0 0 L 10 5 L 0 10" fill="#ad572c"/></marker></defs><text x="24" y="26" font-family="sans-serif" font-size="16" fill="#173746">Native field · c=${r.condition}, t=${r.time}</text>`;
 for(let k=0;k<=4;k++){let v=-extent+k*extent/2;b+=`<path d="M ${x(v)} 50 V 365 M 55 ${y(v)} H 405" stroke="#e3e9ea"/><text x="${x(v)}" y="389" text-anchor="middle" font-family="sans-serif" font-size="12" fill="#526572">${v.toFixed(1)}</text><text x="44" y="${y(v)+4}" text-anchor="end" font-family="sans-serif" font-size="12" fill="#526572">${v.toFixed(1)}</text>`;}
 const parents=[-1,0,1,0,3];r.states.forEach((v,i)=>{if(parents[i]>=0){let a=r.states[parents[i]];b+=`<line x1="${x(a[0])}" y1="${y(a[1])}" x2="${x(v[0])}" y2="${y(v[1])}" stroke="#a7b8bf" stroke-dasharray="4 4"/>`;}});
 r.states.forEach((v,i)=>{let q=r.velocity[i];if(i>0)b+=`<line x1="${x(v[0])}" y1="${y(v[1])}" x2="${x(v[0]+q[0])}" y2="${y(v[1]+q[1])}" stroke="#ad572c" stroke-width="2.5" marker-end="url(#tip)"/>`;b+=`<circle cx="${x(v[0])}" cy="${y(v[1])}" r="12" fill="${i?'#214957':'#087b7a'}"/><text x="${x(v[0])}" y="${y(v[1])+4}" text-anchor="middle" font-family="sans-serif" font-size="12" fill="white">${i}</text>`;});
 b+='<text x="230" y="416" text-anchor="middle" font-family="sans-serif" font-size="13" fill="#526572">Reasoning latent coordinate1 · coordinate2 vertical</text>';return svg('Untrained native field on synthetic complete forest',b);}
function tokenSvg(row){let max=Math.max(...row.candidates.map(x=>x.distance))*1.1;let b=`<text x="22" y="30" font-family="sans-serif" font-size="17" fill="#173746">Node${row.node} · slot${row.slot} · full3D L2</text>`;row.candidates.forEach((c,i)=>{let y=72+i*50;b+=`<text x="22" y="${y}" font-family="monospace" font-size="13" fill="#173746">${esc(c.label)}</text><rect x="150" y="${y-15}" width="${c.distance/max*220}" height="23" rx="3" fill="${i?'#a8bbc0':'#087b7a'}"/><text x="438" y="${y+1}" text-anchor="end" font-family="sans-serif" font-size="13" fill="#173746">${c.distance.toFixed(4)}</text>`;});b+='<text x="22" y="398" font-family="sans-serif" font-size="13" fill="#526572">Shorter is nearer. Six permitted tokens are displayed.</text>';return svg('Nearest permitted token distances from actual untrained projection',b);}
function render(push=true){let r=data.rows.find(x=>x.condition===current.condition&&x.time===current.time);$('vectors').innerHTML=fieldSvg(r);$('phase').textContent=`Available condition ${r.condition}; solver time ${r.time.toFixed(2)}.`;$('velocity-values').innerHTML=r.velocity.map((v,i)=>`<tr><td>${i}</td><td>${f(v[0])}</td><td>${f(v[1])}</td><td>${i?'generated':'clamped'}</td></tr>`).join('');$('hidden-difference').textContent=r.hidden_target_max_difference;$('context-pin').textContent=r.context_sha256;$('field-pin').textContent=r.field_sha256;$('nearest').innerHTML=tokenSvg(data.nearest_token_examples.find(x=>x.node===current.node&&x.slot===current.slot));for(const k of Object.keys(current))$(k).value=current[k];if(push)history.replaceState(null,'','#'+new URLSearchParams(current).toString());}
function restore(){let p=new URLSearchParams(location.hash.slice(1));for(const [k,values]of Object.entries({condition:[1,2],time:[0,.25,.5,.75,1],node:[1,2,3,4],slot:[0,1,2,3]})){let v=p.has(k)?Number(p.get(k)):current[k];if(values.includes(v))current[k]=v;}render(false);}
function download(name,text,type){const url=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),0);}
for(const k of Object.keys(current))$(k).addEventListener('change',()=>{current[k]=Number($(k).value);render();});window.addEventListener('hashchange',restore);
$('candidate-count').textContent=data.batched_candidates;$('parameter-count').textContent=data.new_parameters_excluding_shared_geometry;$('control-count').textContent=data.control_count;
$('quality-values').innerHTML=data.quality_examples.map(x=>`<tr><td>C${x.candidate}</td><td>${x.criteria[0].toFixed(4)}</td><td>${x.criteria[1].toFixed(4)}</td><td>${x.ranking_score.toFixed(4)}</td></tr>`).join('');
const ex=data.analogy_example.exact,ap=data.analogy_example.approximate;$('retrieval').textContent=`Exact: ${ex.identities.join(', ')} (${ex.examined_candidates} examined). One-cell: ${ap.identities.join(', ')||'no eligible memory'} (${ap.examined_candidates} examined; shortfall ${ap.shortfall}).`;
$('export-field').onclick=()=>download('native-forest-field.svg',$('vectors').innerHTML,'image/svg+xml');$('export-token').onclick=()=>download('native-forest-token.svg',$('nearest').innerHTML,'image/svg+xml');$('export-data').onclick=()=>download('native-forest-diagnostic.json',JSON.stringify({selection:current,fixture:data},null,2),'application/json');
restore();window.NativeForestExplorer={ready:true,fixture:data,getState:()=>({...current}),fieldSvg,tokenSvg};
</script></main></body></html>'''
out=ROOT/'docs/project/native-forest-heads.html';out.write_text(PAGE.replace('__DATA__',json.dumps(data,ensure_ascii=True).replace('</','<\\/')))
